values
  ('exam-bac2025-controle-ecrit', 'Bac 2025 (Session de Contrôle) - Épreuve Écrite Systèmes & Technologies de l''Informatique', 180, 20, $json$[{"id":"a-ex1-schema","title":"Partie A, exercice 1 (1) : Interprétation du schéma et insertions (2.5 pts)","type":"modeling","pointsMax":2.5,"questions":[{"id":"A1-ON-1","points":0.125,"type":"code_analysis","explanation":"Oui : codeGouv est une clé étrangère de Ville, une ville n'a donc qu'un gouvernorat."},{"id":"A1-ON-2","points":0.125,"type":"code_analysis","explanation":"Non : codeInc est une clé étrangère simple dans Intervention, une intervention vise un seul incendie."},{"id":"A1-ON-3","points":0.125,"type":"code_analysis","explanation":"Oui : codeTypeInt est une clé étrangère de Intervention, un type peut être utilisé par plusieurs interventions."},{"id":"A1-ON-4","points":0.125,"type":"code_analysis","explanation":"Non : statutInc vaut « E » si l'incendie est éteint suite à une intervention."},{"id":"A1-ON-5","points":0.125,"type":"code_analysis","explanation":"Non : si l'incendie est actif, le champ dateHeureExt ne contient aucune valeur (NULL)."},{"id":"A1-ON-6","points":0.125,"type":"code_analysis","explanation":"Oui : plusieurs lignes de Intervention peuvent référencer le même codeInc."},{"id":"A1-ON-7","points":0.125,"type":"code_analysis","explanation":"Non : codeVille est une clé étrangère simple de Foret, une forêt appartient à une seule ville."},{"id":"A1-ON-8","points":0.125,"type":"code_analysis","explanation":"Non : codeForet est une clé étrangère simple de Incendie."},{"id":"A1-ERR-1","points":0.5,"type":"representation","explanation":"Ligne 3, table Foret, champ codeVille : « V00003 » n'existe pas dans Ville (V0003) : intégrité référentielle."},{"id":"A1-ERR-2","points":0.5,"type":"representation","explanation":"Ligne 4, table Foret, champ superficieForet : -47.000 n'est pas strictement positif : intégrité de domaine."},{"id":"A1-ERR-3","points":0.5,"type":"representation","explanation":"Ligne 7, table Ville, champ codeVille : « V0006 » existe déjà (ligne 6) : intégrité de table (clé primaire)."}]},{"id":"a-ex1-contraintes","title":"Partie A, exercice 1 (2) : Contraintes d'intégrité (0.75 pt)","type":"qcm","pointsMax":0.75,"questions":[{"id":"A1-Q2-A","points":0.125,"multiple":false,"correctAnswers":["opt-default"],"explanation":"DEFAULT 'A' fixe la valeur par défaut du champ."},{"id":"A1-Q2-B","points":0.125,"multiple":false,"correctAnswers":["opt-references"],"explanation":"REFERENCES (clé étrangère) relie Ville à Gouvernorat."},{"id":"A1-Q2-C","points":0.125,"multiple":false,"correctAnswers":["opt-notnull"],"explanation":"NOT NULL rend la saisie obligatoire."},{"id":"A1-Q2-D","points":0.125,"multiple":false,"correctAnswers":["opt-unique"],"explanation":"UNIQUE interdit les doublons."},{"id":"A1-Q2-E","points":0.125,"multiple":false,"correctAnswers":["opt-delete"],"explanation":"ON DELETE CASCADE propage la suppression aux enregistrements liés."},{"id":"A1-Q2-F","points":0.125,"multiple":false,"correctAnswers":["opt-alter"],"explanation":"ALTER TABLE ... ADD CONSTRAINT modifie la structure de la table."}]},{"id":"a-ex2-requete-r","title":"Partie A, exercice 2 : Interprétation de la requête R (1.75 pt)","type":"sql","pointsMax":1.75,"questions":[{"id":"A2-R1","points":0.75,"type":"code_analysis","explanation":"Trois lignes : Aérienne 220 (20 + 200), Terrestre 280 (80 + 100 + 100) et Mixte 70 ; Maritime n'a aucune intervention dans l'extrait. Colonnes : description et SuperficieTotale."},{"id":"A2-R2","points":0.5,"type":"code_analysis","explanation":"Elle affiche, pour chaque type d'intervention, la superficie totale traitée (somme des superficies des interventions)."},{"id":"A2-R3","points":0.5,"type":"query","explanation":"Ajout de HAVING SUM(superficieInt) >= 120 après le GROUP BY."}]},{"id":"a-ex3-structure","title":"Partie A, exercice 3 (1) : Manipulation de la structure (1 pt)","type":"qcm","pointsMax":1.0,"questions":[{"id":"A3-Q1-A","points":0.25,"multiple":false,"correctAnswers":["opt-drop"],"explanation":"ALTER TABLE ... DROP colonne supprime un champ."},{"id":"A3-Q1-B","points":0.25,"multiple":false,"correctAnswers":["opt-update"],"explanation":"Modifier des valeurs existantes se fait avec UPDATE ... SET ... WHERE."},{"id":"A3-Q1-C","points":0.25,"multiple":false,"correctAnswers":["opt-rename"],"explanation":"Le renommage d'un champ est une modification de structure : ALTER TABLE."},{"id":"A3-Q1-D","points":0.25,"multiple":false,"correctAnswers":["opt-modify"],"explanation":"MODIFY change le type ou la taille d'un champ existant."}]},{"id":"a-ex3-sql","title":"Partie A, exercice 3 (2 et 3) : Insertion et requêtes SQL (4.5 pts)","type":"sql","pointsMax":4.5,"questions":[{"id":"A3-Q2","points":1.0,"type":"dml","explanation":"INSERT en omettant dateHeureFinInt (intervention non achevée : NULL)."},{"id":"A3-Q3-A","points":0.5,"type":"query","explanation":"Jointure Foret-Ville-Gouvernorat puis filtre sur nomGouv."},{"id":"A3-Q3-B","points":0.5,"type":"query","explanation":"Jointure Foret-Incendie, filtre YEAR(dateHeureInc) = 2024 et COUNT par forêt."},{"id":"A3-Q3-C","points":0.75,"type":"query","explanation":"Jointure Ville-Foret-Incendie, période du 1er juin au 31 août 2023 et SUM par ville."},{"id":"A3-Q3-D","points":0.5,"type":"query","explanation":"Triple jointure et DISTINCT : un incendie peut avoir plusieurs interventions aériennes."},{"id":"A3-Q3-E","points":0.75,"type":"query","explanation":"Jointures Incendie-Foret-Intervention, GROUP BY et HAVING COUNT(*) >= 3."},{"id":"A3-Q3-F","points":0.5,"type":"query","explanation":"Sous-requête avec MAX : plusieurs forêts peuvent partager la plus grande superficie."}]},{"id":"a-ex4-extension","title":"Partie A, exercice 4 : Extension de la base (1.5 pt)","type":"modeling","pointsMax":1.5,"questions":[{"id":"A4-Q1","points":0.5,"type":"representation","explanation":"Espece(#codeEspece, nomEspece, typeEspece) ; ImpactEspece(#codeImpact, codeEspece#, codeIncendie#, populationAffectee)."},{"id":"A4-Q2","points":0.5,"type":"representation","explanation":"La clé primaire devient composée : ImpactEspece(#codeEspece#, #codeIncendie#, populationAffectee), sans codeImpact : un couple (espèce, incendie) n'apparaît qu'une fois."},{"id":"A4-Q3","points":0.5,"type":"representation","explanation":"StatutEspece(#codeStatut, libelle) et Espece(#codeEspece, nomEspece, typeEspece, codeStatut#) : la clé étrangère va du côté « plusieurs »."}]},{"id":"b-ex1-html","title":"Partie B, exercice 1 : Analyse du code HTML (3 pts)","type":"code_analysis","pointsMax":3.0,"questions":[{"id":"B1-A-1","points":0.125,"type":"code_analysis","explanation":"<title> donne le titre de la page Web, pas celui d'un tableau."},{"id":"B1-A-2","points":0.125,"type":"code_analysis","explanation":"<title> est le titre de la page Web (onglet du navigateur)."},{"id":"B1-A-3","points":0.125,"type":"code_analysis","explanation":"L'auteur se définit par <meta name=\"author\">."},{"id":"B1-B-1","points":0.125,"type":"code_analysis","explanation":"<header> contient le contenu introductif ou de navigation."},{"id":"B1-B-2","points":0.125,"type":"code_analysis","explanation":"Le contenu principal est dans <main> ou <section>."},{"id":"B1-B-3","points":0.125,"type":"code_analysis","explanation":"<header> est placé dans <body>."},{"id":"B1-C-1","points":0.125,"type":"code_analysis","explanation":"Le lien pointe vers une autre page : lien externe."},{"id":"B1-C-2","points":0.125,"type":"code_analysis","explanation":"Le lien pointe vers une autre page (avec une ancre) : lien externe."},{"id":"B1-C-3","points":0.125,"type":"code_analysis","explanation":"#stat est une ancre de la même page : lien interne."},{"id":"B1-D-1","points":0.125,"type":"code_analysis","explanation":"required n'interdit pas la saisie (c'est le rôle de disabled)."},{"id":"B1-D-2","points":0.125,"type":"code_analysis","explanation":"La valeur initiale se donne avec value."},{"id":"B1-D-3","points":0.125,"type":"code_analysis","explanation":"required rend la saisie obligatoire avant l'envoi du formulaire."},{"id":"B1-L-1","points":0.25,"type":"code_analysis","explanation":"Dans le <div> du bouton Envoyer : ligne 34."},{"id":"B1-L-2","points":0.25,"type":"code_analysis","explanation":"Dans <header>, sous le <h1> : ligne 11."},{"id":"B1-L-3","points":0.25,"type":"code_analysis","explanation":"Après la section, avant </body> : ligne 38."},{"id":"B1-L-4","points":0.25,"type":"code_analysis","explanation":"Avant les cases à cocher : ligne 27."},{"id":"B1-L-5","points":0.25,"type":"code_analysis","explanation":"Après </head>, avant <header> : ligne 8."},{"id":"B1-L-6","points":0.25,"type":"code_analysis","explanation":"Dans <head>, ligne 5."}]},{"id":"b-ex2-css","title":"Partie B, exercice 2 (1) : Analyse du code CSS (0.5 pt)","type":"qcm","pointsMax":0.5,"questions":[{"id":"B2-A","points":0.125,"multiple":false,"correctAnswers":["opt-menu-inline"],"explanation":"Les éléments ont class=\"menu\" : sélecteur de classe .menu ; display: inline les aligne."},{"id":"B2-B","points":0.125,"multiple":false,"correctAnswers":["opt-a"],"explanation":"Les liens sont des éléments <a> : sélecteur a."},{"id":"B2-C","points":0.125,"multiple":false,"correctAnswers":["opt-image"],"explanation":"background-size dimensionne l'image d'arrière-plan, pas le bouton."},{"id":"B2-D","points":0.125,"multiple":false,"correctAnswers":["opt-bgimage"],"explanation":"background-image : url(...) définit l'image de fond."}]},{"id":"b-analyse","title":"Partie B, exercices 2 (2), 3 et 4 : règle CSS, JavaScript et PHP (4.5 pts)","type":"code_analysis","pointsMax":4.5,"questions":[{"id":"B2-ROLE","points":0.5,"type":"code_analysis","explanation":"Quand la souris survole un bouton, son texte s'affiche en majuscules."},{"id":"B3-T-1","points":0.125,"type":"code_analysis","explanation":"L'élément attendu est String()."},{"id":"B3-T-2","points":0.125,"type":"code_analysis","explanation":"L'élément attendu est new Date()."},{"id":"B3-T-3","points":0.125,"type":"code_analysis","explanation":"L'élément attendu est getDate()."},{"id":"B3-T-4","points":0.125,"type":"code_analysis","explanation":"L'élément attendu est value."},{"id":"B3-T-5","points":0.125,"type":"code_analysis","explanation":"L'élément attendu est checked."},{"id":"B3-T-6","points":0.125,"type":"code_analysis","explanation":"L'élément attendu est getElementsByName()."},{"id":"B3-T-7","points":0.125,"type":"code_analysis","explanation":"L'élément attendu est alert()."},{"id":"B3-T-8","points":0.125,"type":"code_analysis","explanation":"L'élément attendu est return."},{"id":"B3-TRACE-1","points":0.25,"type":"code_analysis","explanation":"i passe de -1 à 0 : interventions[0].checked vaut true, test devient true et la boucle s'arrête ; la fonction retourne true."},{"id":"B3-TRACE-2","points":0.25,"type":"code_analysis","explanation":"i prend les valeurs 0, 1, 2 puis 3 ; checked vaut toujours false, test reste false ; la fonction retourne false."},{"id":"B3-ROLE","points":0.5,"type":"code_analysis","explanation":"Elle vérifie si au moins un type d'intervention (une case à cocher) est coché."},{"id":"B4-T-1","points":0.25,"type":"code_analysis","explanation":"La fonction attendue est mysqli_connect."},{"id":"B4-T-2","points":0.25,"type":"code_analysis","explanation":"La fonction attendue est count($types)."},{"id":"B4-T-3","points":0.25,"type":"code_analysis","explanation":"La fonction attendue est strlen($ch)."},{"id":"B4-T-4","points":0.25,"type":"code_analysis","explanation":"La fonction attendue est substr($ch,0,$L-1)."},{"id":"B4-T-5","points":0.25,"type":"code_analysis","explanation":"La fonction attendue est mysqli_query($con,$req)."},{"id":"B4-T-6","points":0.25,"type":"code_analysis","explanation":"La fonction attendue est mysqli_num_rows($res)."},{"id":"B4-T-7","points":0.25,"type":"code_analysis","explanation":"La fonction attendue est mysqli_fetch_array($res)."},{"id":"B4-T-8","points":0.25,"type":"code_analysis","explanation":"La fonction attendue est mysqli_close($con)."}]}]$json$::jsonb)
